import { describe, expect, test } from 'bun:test';
import { formatResultsTable } from '../utils/tableFormatter.js';

describe('formatResultsTable', () => {
  test('basic 2-column, 2-row table contains box-drawing characters', () => {
    const result = formatResultsTable([
      { player: 'LeBron James', points: 30 },
      { player: 'S. Curry', points: 28 },
    ]);
    expect(result).toContain('┌');
    expect(result).toContain('┐');
    expect(result).toContain('└');
    expect(result).toContain('┘');
    expect(result).toContain('├');
    expect(result).toContain('┤');
    expect(result).toContain('│');
    expect(result).toContain('─');
    expect(result).toContain('LeBron James');
    expect(result).toContain('S. Curry');
  });
});

export function formatResultsTable(results: Record<string, unknown>[]): string {
  if (results.length === 0) {
    return 'Query returned no results.';
  }

  const headers = Object.keys(results[0]!);
  const rows = results.map((row) =>
    headers.map((h) => {
      const val = row[h];
      return val === null || val === undefined ? '' : String(val);
    })
  );

  const colWidths = headers.map((h, i) => {
    const maxVal = Math.max(...rows.map((r) => r[i]!.length));
    return Math.max(h.length, maxVal);
  });

  const isNumeric = headers.map((_, i) =>
    rows.every((r) => {
      const v = r[i]!;
      return v !== '' && !isNaN(Number(v));
    })
  );

  const topLine =
    '┌' + colWidths.map((w) => '─'.repeat(w + 2)).join('┬') + '┐';
  const headerLine =
    '│ ' +
    headers.map((h, i) => h.padEnd(colWidths[i]!)).join(' │ ') +
    ' │';
  const sepLine =
    '├' + colWidths.map((w) => '─'.repeat(w + 2)).join('┼') + '┤';
  const dataLines = rows.map(
    (r) =>
      '│ ' +
      r
        .map((v, i) =>
          isNumeric[i] ? v.padStart(colWidths[i]!) : v.padEnd(colWidths[i]!)
        )
        .join(' │ ') +
      ' │'
  );
  const botLine =
    '└' + colWidths.map((w) => '─'.repeat(w + 2)).join('┴') + '┘';

  const lines = [topLine, headerLine, sepLine, ...dataLines, botLine];

  if (results.length > 20) {
    lines.unshift(`Rows: ${results.length} (showing first 20)`);
  }

  return lines.join('\n');
}

